    "$('bkdo').onclick=function(){setHtml('bklist','');bkMsg('…');\n"
    "if(BKW=='device'){postj('/api/backup?where=download',null,function(st,j,txt){if(st!=200){bkMsg(t('bkFail'),'bad');return}\n"
    "try{var a=document.createElement('a'),u=URL.createObjectURL(new Blob([txt],{type:'application/json'}));a.href=u;a.download='hearbridge-backup.json';document.body.appendChild(a);a.click();\n"
    "setTimeout(function(){URL.revokeObjectURL(u);a.parentNode.removeChild(a)},1000);bkMsg(t('bkDownloaded'),'good')}catch(e){bkMsg(t('bkFail'),'bad')}});return}\n"
    "postj('/api/backup?where='+BKW,null,function(st,j){if(st==200&&j&&j.ok)bkMsg(t('bkSaved').replace('%s',j.name),'good');else if(st==409)bkMsg(t('bkNoUsb'),'bad');else bkMsg(t('bkFail'),'bad')})};\n"
    "function bkRestored(st,j){if(st==200&&j&&j.ok){bkMsg(t('bkRestored'),'good');setHtml('bklist','');saved()}else bkMsg(t('bkFail'),'bad')}\n"
    "$('rsdo').onclick=function(){bkMsg('');setHtml('bklist','');\n"
    "if(BKW=='device'){$('bkfile').value='';$('bkfile').click();return}\n"
    "getj('/api/backups?where='+BKW,function(j){var f=j.files||[],h='',i;if(!j.avail){bkMsg(t('bkNoUsb'),'bad');return}\n"
    "if(!f.length){bkMsg(t('bkNone'));return}bkMsg(t('bkPick'));\n"
    "for(i=0;i<f.length;i++)h+='<button type=\"button\" data-n=\"'+esc(f[i].name)+'\">'+esc(f[i].when||t('bkLatest'))+'</button>';\n"
    "setHtml('bklist',h);var b=$('bklist').getElementsByTagName('button');\n"
    "for(i=0;i<b.length;i++)b[i].onclick=function(){if(!confirm(t('restoreConfirm')))return;bkMsg('…');postj('/api/restore?where='+BKW+'&name='+this.getAttribute('data-n'),null,bkRestored)};b.length&&b[0].focus()})};\n"
    "$('bkfile').onchange=function(){var f=this.files&&this.files[0];if(!f)return;if(!confirm(t('restoreConfirm')))return;\n"
    "var r=new FileReader();r.onload=function(){bkMsg('…');postj('/api/restore?where=upload',r.result,bkRestored)};r.readAsText(f)};\n"
    "/* latency: estimate from the stream loop (see hb_latency_estimate) */\n"
    "var busyL=0,latT=0,latAck=-1,latTouch=0,LATCOL=['var(--b0)','var(--b1)','var(--b3)','var(--b4)'];\n"
    "function pushLat(v){v=parseInt(v,10);if(!(v>=40&&v<=200)||v===latAck)return;latAck=v;latTouch=0;busyL=1;\n"
    "$('latt').textContent=v+' ms';act('/api/latency?ms='+v,function(){busyL=0})}\n"
    "function drawLat(){var L=S.latency;if(!L)return;\n"
    "var ms=L.target_ms;if(ms>200)ms=200;if(ms<40)ms=40;\n"
    "var cur=parseInt($('lat').value,10);\n"
    "if(latTouch&&cur>=40&&cur<=200&&cur!==ms)pushLat(cur);\n"
    "else if(!busyL){$('lat').value=ms;latAck=ms}\n"
    "$('latt').textContent=(latTouch||busyL?$('lat').value:ms)+' ms';\n"
    "var on=S.connected&&L.estimate_ms>0;$('latv').textContent=on?'≈ '+L.estimate_ms+' ms':'-';\n"
    "var parts=[L.capture_ms+L.packet_ms,L.queue_ms,L.radio_ms,L.sink_ms],names=['latPipe','latQueue','latRadio',L.sink_reported?'latSink':'latSinkTyp'],tot=0,i,h='';\n"
    "for(i=0;i<4;i++)tot+=parts[i];\n"
    "for(i=0;i<4;i++){$('lb'+i).style.width=(on&&tot?parts[i]*100/tot:0)+'%';\n"
    "h+='<span><b style=\"background:'+LATCOL[i]+'\"></b>'+esc(t(names[i]))+' <em>'+(on?parts[i]:'-')+' ms</em></span>'}\n"
    "setHtml('lkeys',h)}\n"
    "/* equalizer: same RBJ filters as src/a2dp/eq.c, drawn as a curve */\n"
    "var EQHZ=[80,250,1000,3500,10000],EQQ=[.707,1,1,1,.707],EQCOL=['#ff6a2b','#ffb23d','#c8ff3d','#3dd8ff','#ff7ad9'],\n"
    "PRESETS=[[0,0,0,0,0],[6,3,0,0,0],[-6,-3,0,0,0],[0,0,0,3,6],[-3,-1,2,5,2]],EQ=null,busyE=0,eqT=0;\n"
    "function biq(b,g){var A=Math.pow(10,g/40),w=2*Math.PI*EQHZ[b]/48000,c=Math.cos(w),s=Math.sin(w),q=EQQ[b],r;\n"
    "if(b==0||b==4){var sa=2*Math.sqrt(A)*s/(2*q);r=b==0?[A*((A+1)-(A-1)*c+sa),2*A*((A-1)-(A+1)*c),A*((A+1)-(A-1)*c-sa),(A+1)+(A-1)*c+sa,-2*((A-1)+(A+1)*c),(A+1)+(A-1)*c-sa]\n"
    ":[A*((A+1)+(A-1)*c+sa),-2*A*((A-1)+(A+1)*c),A*((A+1)+(A-1)*c-sa),(A+1)-(A-1)*c+sa,2*((A-1)-(A+1)*c),(A+1)-(A-1)*c-sa]}\n"
    "else{var al=s/(2*q);r=[1+al*A,-2*c,1-al*A,1+al/A,-2*c,1-al/A]}return r}\n"
    "function eqResp(db,hz){var w=2*Math.PI*hz/48000,t=0,b;for(b=0;b<5;b++){if(!db[b])continue;var k=biq(b,db[b]),\n"
    "nr=k[0]+k[1]*Math.cos(w)+k[2]*Math.cos(2*w),ni=-(k[1]*Math.sin(w)+k[2]*Math.sin(2*w)),dr=k[3]+k[4]*Math.cos(w)+k[5]*Math.cos(2*w),di=-(k[4]*Math.sin(w)+k[5]*Math.sin(2*w));\n"
    "t+=10*Math.log((nr*nr+ni*ni)/(dr*dr+di*di))/Math.LN10}return t}\n"
    "function eqVals(){var v=[],i;for(i=0;i<5;i++)v.push(parseInt($('eq'+i).value,10)||0);return v}\n"
    "function eqPaint(db,on){var d='',i,x,y,n=60;for(i=0;i<=n;i++){x=i*300/n;var hz=20*Math.pow(1000,i/n);\n"
    "y=50-eqResp(db,hz)*50/14;if(y<1)y=1;if(y>99)y=99;d+=(i?'L':'M')+x.toFixed(1)+' '+y.toFixed(1)}\n"
    "$('eqline').setAttribute('d',d);$('eqfill').setAttribute('d',d+'L300 50L0 50Z');\n"
    "for(i=0;i<5;i++){var v=db[i],p=(v+12)/24*100,lo=Math.min(50,p),hi=Math.max(50,p);\n"
    "$('eqv'+i).textContent=(v>0?'+':'')+v+' dB';\n"
    "$('eq'+i).style.setProperty('--trk','linear-gradient(90deg,#0c0b0f '+lo+'%,'+EQCOL[i]+'aa '+lo+'%,'+EQCOL[i]+'aa '+hi+'%,#0c0b0f '+hi+'%)')}\n"
    "var anyp=0;for(i=0;i<PRESETS.length;i++){var m=PRESETS[i].join()==db.join();$('pr'+i).className=m?'act':'';if(m)anyp=1}$('prc').className=anyp?'':'act';\n"
    "$('eqp').className='panel eqp'+(on?'':' off');$('eqon').className=on?'act':'';$('eqon').textContent=t(on?'eqOn':'eqOff')}\n"
    "function drawEq(){if(!S.eq)return;if(!busyE&&Date.now()-eqT>1500){var i;for(i=0;i<5;i++)$('eq'+i).value=S.eq.db[i];EQ=S.eq}\n"
    "eqPaint(busyE?eqVals():S.eq.db,S.eq.on)}\n"
    "function eqSend(db,on){var q='/api/eq?on='+(on?1:0),i;for(i=0;i<5;i++)q+='&b'+i+'='+db[i];eqT=Date.now();act(q,function(){busyE=0})}\n"
    "for(var ei=0;ei<5;ei++){$('eq'+ei).oninput=function(){busyE=1;eqPaint(eqVals(),S&&S.eq&&S.eq.on)};\n"
    "$('eq'+ei).onchange=function(){eqSend(eqVals(),1)}}\n"
    "for(var pi=0;pi<5;pi++)$('pr'+pi).onclick=(function(p){return function(){var i;for(i=0;i<5;i++)$('eq'+i).value=PRESETS[p][i];\n"
    "busyE=1;eqPaint(PRESETS[p],1);eqSend(PRESETS[p],1)}})(pi);\n"
    "$('eqon').onclick=function(){var on=!(S&&S.eq&&S.eq.on);eqSend(eqVals(),on)};\n"
    "$('gain').oninput=function(){busyG=1;$('gv').textContent=pct(this.value)};\n"
    "$('gain').onchange=function(){act('/api/volume?pct='+this.value,function(){busyG=0})};\n"
    "/* headset volume: send on release (any of these events; the PS5 browser may skip change),\n"
    "   and never keep the slider frozen: after 1.5 s without input it follows the headset again */\n"
    "var hsT=0,hsSent=-1;\n"
    "function hsPush(){var v=parseInt($('hs').value,10);if(v!==hsSent){hsSent=v;act('/api/headset?vol='+v,function(){busyH=0})}else busyH=0}\n"
    "$('hs').oninput=function(){busyH=1;hsT=Date.now();$('hv').textContent=pct(this.value*100/127)};\n"
    "$('hs').onchange=$('hs').onmouseup=$('hs').ontouchend=$('hs').onpointerup=hsPush;\n"
    "setInterval(function(){if(busyH&&Date.now()-hsT>1500)hsPush()},300);\n"
    "$('mute').onclick=function(){act('/api/mute?on='+(S&&S.muted?0:1))};\n"
    "$('tone').onclick=function(){act('/api/tone?on='+(S&&S.tone?0:1))};\n"
    "$('clean').onclick=function(){act('/api/clean')};\n"
    "function markLat(){latTouch=1;$('latt').textContent=$('lat').value+' ms';pushLat($('lat').value)}\n"
    "$('lat').oninput=markLat;$('lat').onchange=markLat;\n"
    "$('lat').onmouseup=markLat;$('lat').ontouchend=markLat;$('lat').onpointerup=markLat;\n"
    "for(var cj=0;cj<4;cj++)$('cd'+cj).onclick=(function(m){return function(){if(!this.disabled)act('/api/codec?mode='+m)}})(cj);\n"
    "function armScan(){scanLive=Date.now()+12000;$('scanning').style.display='';devices()}\n"
    "$('scan').onclick=function(){act('/api/scan');armScan()};\n"
    "$('stop').onclick=function(){if(confirm(t('stopConfirm')))act('/api/stop')};\n"
    "buildLangs();\n"
    "(function(){var c=null,m=/[?&]lang=([a-z]{2})/.exec(location.search);if(m)c=m[1];else try{c=localStorage.getItem('hb_lang')}catch(e){}\n"
    "if(!c){var n=(navigator.language||'en').slice(0,2).toLowerCase();c=info(n).code==n?n:'en'}setLang(c)})();\n"
    "req('/api/status');act('/api/scan');armScan();setInterval(function(){req('/api/status');if(S&&!fresh())draw()},1000);\n"
    "/* Back to the page (PS5 browser resumes a background tab late): ask now. */\n"
    "if(document.addEventListener)document.addEventListener('visibilitychange',function(){if(!document.hidden){req('/api/status');saved()}});\n"
    "setInterval(function(){if(scanLive&&Date.now()<scanLive)devices()},300);\n"
    "setInterval(function(){var v=parseInt($('lat').value,10);if(latAck>=0&&v!==latAck){latTouch=1;pushLat(v)}},200);\n"
    "hbTest={req:req,draw:function(){draw()},badge:badge};\n"
    "</script></body></html>\n";

#endif
